#endif  // KRPC_TYPE_TUPLE_DOUBLE_DOUBLE_DOUBLE

/**
 * The launch mode of the ascent autopilot. See krpc_MechJeb_AscentGuidance_LaunchMode().
 */
typedef enum {
  /**
   * The autopilot is not performing a timed launch.
   */
  KRPC_MECHJEB_ASCENTLAUNCHMODE_NORMAL = 0,
  /**
   * A timed launch to rendezvous with the target vessel.
   */
  KRPC_MECHJEB_ASCENTLAUNCHMODE_RENDEZVOUS = 1,
  /**
   * A timed launch into the plane of the target.
   */
  KRPC_MECHJEB_ASCENTLAUNCHMODE_TARGETPLANE = 2,
  /**
   * A timed launch to the target's longitude of the ascending node. See
   * krpc_MechJeb_AscentGuidance_LaunchToMatchLan().
   */
  KRPC_MECHJEB_ASCENTLAUNCHMODE_MATCHLAN = 3,
  /**
   * A timed launch to a longitude of the ascending node. See
   * krpc_MechJeb_AscentGuidance_LaunchToLan().
   */
  KRPC_MECHJEB_ASCENTLAUNCHMODE_LAN = 4,
  /**
   * A timed launch of another kind, started from MechJeb's window.
   */
  KRPC_MECHJEB_ASCENTLAUNCHMODE_UNKNOWN = 99
} krpc_MechJeb_AscentLaunchMode_t;

/**
 * The ascent path. See krpc_MechJeb_AscentGuidance_AscentType().
 */
typedef enum {
  /**
   * The classic ascent path. See krpc_MechJeb_AscentGuidance_ClassicPath().
   */
  KRPC_MECHJEB_ASCENTTYPE_CLASSIC = 0,
  /**
   * Primer Vector Guidance, for RSS/RO. See krpc_MechJeb_AscentGuidance_PVGSettings().
   */
  KRPC_MECHJEB_ASCENTTYPE_PVG = 1
} krpc_MechJeb_AscentType_t;

/**
 * An attitude controller of MechJeb. See krpc_MechJeb_AttitudeAdjustment_Controller().
 */
typedef enum {
  /**
   * MechJeb's original attitude controller.
   */
  KRPC_MECHJEB_ATTITUDECONTROLLER_MJ = 0,
  /**
   * The attitude controller of kOS.
   */
  KRPC_MECHJEB_ATTITUDECONTROLLER_KOS = 1,
  /**
   * A hybrid of the MechJeb and kOS controllers.
   */
  KRPC_MECHJEB_ATTITUDECONTROLLER_HYBRID = 2,
  /**
   * MechJeb's default controller.
   */
  KRPC_MECHJEB_ATTITUDECONTROLLER_BETTER = 3,
  /**
   * A linear-quadratic regulator.
   */
  KRPC_MECHJEB_ATTITUDECONTROLLER_LQR = 4
} krpc_MechJeb_AttitudeController_t;

/**
 * A reference frame of Smart A.S.S. See krpc_MechJeb_SmartASS_AdvancedReference().
 */
typedef enum {
  /**
   * The world coordinate system.
   */
  KRPC_MECHJEB_ATTITUDEREFERENCE_INERTIAL = 0,
  /**
   * Forward is prograde, left is normal and up is radial out.
   */
  KRPC_MECHJEB_ATTITUDEREFERENCE_ORBIT = 1,
  /**
   * Forward is the orbital velocity projected onto the surface, and up is the surface normal.
   */
  KRPC_MECHJEB_ATTITUDEREFERENCE_ORBITHORIZONTAL = 2,
  /**
   * Forward is north, left is west and up is the surface normal.
   */
  KRPC_MECHJEB_ATTITUDEREFERENCE_SURFACENORTH = 3,
  /**
   * Forward is the surface velocity, and up is the surface normal perpendicular to it.
   */
  KRPC_MECHJEB_ATTITUDEREFERENCE_SURFACEVELOCITY = 4,
  /**
   * Forward is toward the target, and up is the vessel's heading perpendicular to it.
   */
  KRPC_MECHJEB_ATTITUDEREFERENCE_TARGET = 5,
  /**
   * Forward is the velocity relative to the target.
   */
  KRPC_MECHJEB_ATTITUDEREFERENCE_RELATIVEVELOCITY = 6,
  /**
   * Forward is the direction the target faces, and up is the target's up.
   */
  KRPC_MECHJEB_ATTITUDEREFERENCE_TARGETORIENTATION = 7,
  /**
   * Forward is the burn direction of the next maneuver node.
   */
  KRPC_MECHJEB_ATTITUDEREFERENCE_MANEUVERNODE = 8,
  /**
   * Forward is the orbital velocity of the body that orbits the sun, and up is radial
   * out of that orbit.
   */
  KRPC_MECHJEB_ATTITUDEREFERENCE_SUN = 9,
  /**
   * Forward is the horizontal surface velocity, and up is the surface normal.
   */
  KRPC_MECHJEB_ATTITUDEREFERENCE_SURFACEHORIZONTAL = 10
} krpc_MechJeb_AttitudeReference_t;

/**
 * The result of the differential throttle. See
 * krpc_MechJeb_ThrustLimiter_DifferentialThrottleStatus().
 */
typedef enum {
  /**
   * The throttles balance the thrust.
   */
  KRPC_MECHJEB_DIFFERENTIALTHROTTLESTATUS_SUCCESS = 0,
  /**
   * All the engines are off.
   */
  KRPC_MECHJEB_DIFFERENTIALTHROTTLESTATUS_ALLENGINESOFF = 1,
  /**
   * The vessel needs more engines.
   */
  KRPC_MECHJEB_DIFFERENTIALTHROTTLESTATUS_MOREENGINESREQUIRED = 2,
  /**
   * The solver found no solution.
   */
  KRPC_MECHJEB_DIFFERENTIALTHROTTLESTATUS_SOLVERFAILED = 3
} krpc_MechJeb_DifferentialThrottleStatus_t;

/**
 * A direction of Smart A.S.S. See krpc_MechJeb_SmartASS_AdvancedDirection().
 */
typedef enum {
  /**
   * Forward.
   */
  KRPC_MECHJEB_DIRECTION_FORWARD = 0,
  /**
   * Back.
   */
  KRPC_MECHJEB_DIRECTION_BACK = 1,
  /**
   * Up.
   */
  KRPC_MECHJEB_DIRECTION_UP = 2,
  /**
   * Down.
   */
  KRPC_MECHJEB_DIRECTION_DOWN = 3,
  /**
   * Right.
   */
  KRPC_MECHJEB_DIRECTION_RIGHT = 4,
  /**
   * Left.
   */
  KRPC_MECHJEB_DIRECTION_LEFT = 5
} krpc_MechJeb_Direction_t;

/**
 * A throttle limiter. See krpc_MechJeb_ThrustLimiter_Limiter().
 */
typedef enum {
  /**
   * No limiter limits the throttle.
   */
  KRPC_MECHJEB_LIMITMODE_NONE = 0,
  /**
   * The terminal velocity limit.
   */
  KRPC_MECHJEB_LIMITMODE_TERMINALVELOCITY = 1,
  /**
   * krpc_MechJeb_ThrustLimiter_LimitToPreventOverheats().
   */
  KRPC_MECHJEB_LIMITMODE_TEMPERATURE = 2,
  /**
   * krpc_MechJeb_ThrustLimiter_LimitToPreventFlameout().
   */
  KRPC_MECHJEB_LIMITMODE_FLAMEOUT = 3,
  /**
   * krpc_MechJeb_ThrustLimiter_LimitAcceleration().
   */
  KRPC_MECHJEB_LIMITMODE_ACCELERATION = 4,
  /**
   * krpc_MechJeb_ThrustLimiter_LimitThrottle().
   */
  KRPC_MECHJEB_LIMITMODE_THROTTLE = 5,
  /**
   * krpc_MechJeb_ThrustLimiter_LimitDynamicPressure().
   */
  KRPC_MECHJEB_LIMITMODE_DYNAMICPRESSURE = 6,
  /**
   * krpc_MechJeb_ThrustLimiter_LimiterMinThrottle().
   */
  KRPC_MECHJEB_LIMITMODE_MINTHROTTLE = 7,
  /**
   * krpc_MechJeb_ThrustLimiter_ElectricThrottle().
   */
  KRPC_MECHJEB_LIMITMODE_ELECTRIC = 8,
  /**
   * krpc_MechJeb_ThrustLimiter_LimitToPreventUnstableIgnition().
   */
  KRPC_MECHJEB_LIMITMODE_UNSTABLEIGNITION = 9,
  /**
   * krpc_MechJeb_ThrustLimiter_AutoRCSUllaging().
   */
  KRPC_MECHJEB_LIMITMODE_AUTORCSULLAGE = 10
} krpc_MechJeb_LimitMode_t;

/**
 * The autopilot mode of Smart A.S.S. See krpc_MechJeb_SmartASS_AutopilotMode().
 */
typedef enum {
  /**
   * Off.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_OFF = 0,
  /**
   * Stop the vessel's rotation.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_KILLROT = 1,
  /**
   * Point at the next maneuver node.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_NODE = 2,
  /**
   * Point in the direction set by krpc_MechJeb_SmartASS_SurfaceHeading(),
   * krpc_MechJeb_SmartASS_SurfacePitch() and krpc_MechJeb_SmartASS_SurfaceRoll().
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_SURFACE = 3,
  /**
   * Point orbital prograde.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_PROGRADE = 4,
  /**
   * Point orbital retrograde.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_RETROGRADE = 5,
  /**
   * Point orbit normal.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_NORMALPLUS = 6,
  /**
   * Point orbit anti-normal.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_NORMALMINUS = 7,
  /**
   * Point radially outward.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_RADIALPLUS = 8,
  /**
   * Point radially inward.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_RADIALMINUS = 9,
  /**
   * Point along the velocity relative to the target.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_RELATIVEPLUS = 10,
  /**
   * Point against the velocity relative to the target.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_RELATIVEMINUS = 11,
  /**
   * Point at the target.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_TARGETPLUS = 12,
  /**
   * Point away from the target.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_TARGETMINUS = 13,
  /**
   * Point parallel to the target's orientation. For a docking port, along its axis
   * and away from it.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_PARALLELPLUS = 14,
  /**
   * Point antiparallel to the target's orientation. For a docking port, along its axis
   * and toward it.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_PARALLELMINUS = 15,
  /**
   * Point in the direction set by krpc_MechJeb_SmartASS_AdvancedReference() and
   * krpc_MechJeb_SmartASS_AdvancedDirection().
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_ADVANCED = 16,
  /**
   * Set by MechJeb's autopilots. Cannot be set.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_AUTOMATIC = 17,
  /**
   * Point along the surface velocity.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_SURFACEPROGRADE = 18,
  /**
   * Point against the surface velocity.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_SURFACERETROGRADE = 19,
  /**
   * Point along the horizontal surface velocity.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_HORIZONTALPLUS = 20,
  /**
   * Point against the horizontal surface velocity.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_HORIZONTALMINUS = 21,
  /**
   * Point up, normal to the surface.
   */
  KRPC_MECHJEB_SMARTASSAUTOPILOTMODE_VERTICALPLUS = 22
} krpc_MechJeb_SmartASSAutopilotMode_t;

/**
 * The mode of the Smart A.S.S. window. See krpc_MechJeb_SmartASS_InterfaceMode().
 */
typedef enum {
  /**
   * The orbital modes.
   */
  KRPC_MECHJEB_SMARTASSINTERFACEMODE_ORBITAL = 0,
  /**
   * The surface modes.
   */
  KRPC_MECHJEB_SMARTASSINTERFACEMODE_SURFACE = 1,
  /**
   * The target modes.
   */
  KRPC_MECHJEB_SMARTASSINTERFACEMODE_TARGET = 2,
  /**
   * The advanced mode.
   */
  KRPC_MECHJEB_SMARTASSINTERFACEMODE_ADVANCED = 3,
  /**
   * Set by MechJeb's autopilots. Cannot be set.
   */
  KRPC_MECHJEB_SMARTASSINTERFACEMODE_AUTOMATIC = 4
} krpc_MechJeb_SmartASSInterfaceMode_t;

/**
 * The mode of Smart RCS. See krpc_MechJeb_SmartRCS_Mode().
 */
typedef enum {
  /**
   * Off.
   */
  KRPC_MECHJEB_SMARTRCSMODE_OFF = 0,
  /**
   * Hold zero velocity relative to the target.
   */
  KRPC_MECHJEB_SMARTRCSMODE_ZERORELATIVEVELOCITY = 1,
  /**
   * Hold zero velocity. MechJeb 2.15 removed this mode.
   */
  KRPC_MECHJEB_SMARTRCSMODE_ZEROVELOCITY = 2
} krpc_MechJeb_SmartRCSMode_t;

/**
 * The time reference of a maneuver. See krpc_MechJeb_TimeSelector_TimeReference().
 */
typedef enum {
  /**
   * At the optimum time.
   */
  KRPC_MECHJEB_TIMEREFERENCE_COMPUTED = 0,
  /**
   * After krpc_MechJeb_TimeSelector_LeadTime().
   */
  KRPC_MECHJEB_TIMEREFERENCE_XFROMNOW = 1,
  /**
   * At the next apoapsis.
   */
  KRPC_MECHJEB_TIMEREFERENCE_APOAPSIS = 2,
  /**
   * At the next periapsis.
   */
  KRPC_MECHJEB_TIMEREFERENCE_PERIAPSIS = 3,
  /**
   * At krpc_MechJeb_TimeSelector_CircularizeAltitude().
   */
  KRPC_MECHJEB_TIMEREFERENCE_ALTITUDE = 4,
  /**
   * At the equatorial ascending node.
   */
  KRPC_MECHJEB_TIMEREFERENCE_EQASCENDING = 5,
  /**
   * At the equatorial descending node.
   */
  KRPC_MECHJEB_TIMEREFERENCE_EQDESCENDING = 6,
  /**
   * At the next ascending node with the target.
   */
  KRPC_MECHJEB_TIMEREFERENCE_RELASCENDING = 7,
  /**
   * At the next descending node with the target.
   */
  KRPC_MECHJEB_TIMEREFERENCE_RELDESCENDING = 8,
  /**
   * At the closest approach to the target.
   */
  KRPC_MECHJEB_TIMEREFERENCE_CLOSESTAPPROACH = 9,
  /**
   * At the cheaper of the equatorial ascending and descending nodes.
   */
  KRPC_MECHJEB_TIMEREFERENCE_EQHIGHESTAD = 10,
  /**
   * At the nearer of the equatorial ascending and descending nodes.
   */
  KRPC_MECHJEB_TIMEREFERENCE_EQNEARESTAD = 11,
  /**
   * At the cheaper of the ascending and descending nodes with the target.
   */
  KRPC_MECHJEB_TIMEREFERENCE_RELHIGHESTAD = 12,
  /**
   * At the nearer of the ascending and descending nodes with the target.
   */
  KRPC_MECHJEB_TIMEREFERENCE_RELNEARESTAD = 13
} krpc_MechJeb_TimeReference_t;

/**
 * The mode of Translatron. See krpc_MechJeb_Translatron_Mode().
 */
typedef enum {
  /**
   * Off.
   */
  KRPC_MECHJEB_TRANSLATRONMODE_OFF = 0,
  /**
   * Hold the orbital speed.
   */
  KRPC_MECHJEB_TRANSLATRONMODE_KEEPORBITAL = 1,
  /**
   * Hold the surface speed.
   */
  KRPC_MECHJEB_TRANSLATRONMODE_KEEPSURFACE = 2,
  /**
   * Hold the vertical speed.
   */
  KRPC_MECHJEB_TRANSLATRONMODE_KEEPVERTICAL = 3,
  /**
   * Unused. MechJeb 2.15 has no such mode.
   */
  KRPC_MECHJEB_TRANSLATRONMODE_KEEPRELATIVE = 4,
  /**
   * Set by MechJeb's autopilots. Cannot be set.
   */
  KRPC_MECHJEB_TRANSLATRONMODE_DIRECT = 5
} krpc_MechJeb_TranslatronMode_t;

